// Builds the Telegram caption for each tailored job.
// CHAT_ID: your Telegram chat ID (see setup instructions).
const CHAT_ID = 'YOUR_CHAT_ID';

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const list = a => (Array.isArray(a) && a.length ? a.slice(0, 6).join(', ') : '—');
const MODE = { remote: '🌎 Remote', hybrid: '🏢 Hybrid', onsite: '🏢 On-site', unknown: '' };

return $input.all().map(item => {
  const j = item.json;
  const checks = Array.isArray(j.checks) ? j.checks : [];
  let caption = [
    `<b>${esc(j.title)}</b> — ${esc(j.company)}`,
    `📍 ${esc(j.location ?? '?')} ${MODE[j.work_mode] ?? ''}`,
    `⭐ Score: <b>${j.match_score}</b>/100${j.score_confidence === 'title_only' ? ' (title only)' : ''} · 🗣 ${esc((j.language ?? '?').toUpperCase())}`,
    ``,
    `✅ ${esc(list(j.matched_skills))}`,
    `➖ Missing: ${esc(list(j.missing_skills))}`,
    j.red_flags?.length ? `⚠️ ${esc(list(j.red_flags))}` : null,
    ``,
    `💬 ${esc(j.match_reasoning ?? '')}`,
    checks.length ? `\n🔍 Review fixed: ${esc(checks.slice(0, 3).join('; '))}` : null,
    `\n🆔 Job ${j.id}`,
  ].filter(x => x !== null).join('\n');
  if (caption.length > 1000) caption = caption.slice(0, 990) + '…';   // Telegram caption limit: 1024

  return { json: { chat_id: CHAT_ID, job_id: j.id, caption, cv_file_name: j.cv_file_name } };
});

